	@Test
	void constantFilterHoistingAndLoweringPreserveAnEnclosingJoinOperandBoundary() {
		StatementPattern body = new StatementPattern(Var.of("s"), Var.of("p", P, false, true), Var.of("o"));
		Graph graph = new Graph(Var.of("graph", G1, false, true),
				new Filter(body, new ValueConstant(VF.createLiteral(true))));
		TupleExpr original = joinWithAnObservableGraphBoundary(graph);
		List<BindingSet> expected = evaluate(original, null, EmptyBindingSet.getInstance(), new CatalogSource());
		assertThat(expected).hasSize(3)
				.filteredOn(row -> row.hasBinding("seen"))
				.singleElement()
				.satisfies(row -> assertThat(row.getValue("seen")).isEqualTo(VF.createLiteral(false)));
		TupleExpr plan = original.clone();
		GraphScopeOptimizer optimizer = new GraphScopeOptimizer(QueryExecutionPolicy.DEFAULT
				.withGraphJoinOptimization(GraphJoinOptimization.OFF));
		optimizer.optimize(plan, null, EmptyBindingSet.getInstance());
		new ParentReferenceChecker(optimizer).optimize(plan, null, EmptyBindingSet.getInstance());
		assertThat(nodes(plan, Graph.class)).isEmpty();
		assertThat(evaluate(plan, null, EmptyBindingSet.getInstance(), new CatalogSource()))
				.containsExactlyInAnyOrderElementsOf(expected);
	}

