	@TestFactory
	Stream<DynamicTest> standardPipelinePreservesBagsAcrossGraphJoinPolicies() {
		List<String> queries = List.of(
				"GRAPH ?g { GRAPH ?g { ?s <urn:p> ?o } }",
				"GRAPH ?g { ?s <urn:p> ?o } GRAPH ?g { ?s <urn:q> ?v }",
				"{ GRAPH ?g { ?s <urn:p> ?o } } UNION { GRAPH ?g { ?s <urn:p> ?o } }",
				"GRAPH ?g { ?s <urn:p> ?o } OPTIONAL { GRAPH ?g { ?s <urn:q> ?v } }",
				"GRAPH ?g { ?s <urn:p> ?o } MINUS { GRAPH ?g { ?s <urn:q> ?v } }",
				"GRAPH ?g { ?s <urn:p> ?o } FILTER(?g = <urn:g1>)",
				"GRAPH ?g { ?s <urn:p> ?o } FILTER(?o > 1)",
				"GRAPH <urn:g1> { ?s <urn:p> ?o FILTER(?o > 1) }",
				"VALUES ?wanted { 1 } GRAPH ?g { ?s <urn:p> ?o } FILTER(?o = ?wanted)",
				"GRAPH ?g { FILTER(!BOUND(?g)) } FILTER(sameTerm(?g, <urn:g1>))",
				"GRAPH ?g { { SELECT DISTINCT ?g ?x WHERE { "
						+ "VALUES (?g ?x) { (UNDEF 1) (<urn:g1> 1) } } } }");
		return queries.stream()
				.flatMap(body -> Stream.of(GraphJoinOptimization.OFF, GraphJoinOptimization.AUTO,
						GraphJoinOptimization.FORCE_INDEPENDENT)
						.map(mode -> DynamicTest.dynamicTest(mode + ": " + body, () -> {
							TupleExpr original = parse(body);
							List<BindingSet> expected = evaluate(original, null, EmptyBindingSet.getInstance(),
									new CatalogSource());
							TupleExpr optimized = original.clone();
							DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(new CatalogSource(),
									null);
							strategy.setQueryExecutionPolicy(
									QueryExecutionPolicy.DEFAULT.withGraphJoinOptimization(mode));
							strategy.optimize(optimized, new EvaluationStatistics(), EmptyBindingSet.getInstance());
							List<BindingSet> actual = new ArrayList<>();
							try (CloseableIteration<BindingSet> result = strategy.precompile(optimized)
									.evaluate(EmptyBindingSet.getInstance())) {
								while (result.hasNext()) {
									actual.add(result.next());
								}
							}
							assertThat(actual).containsExactlyInAnyOrderElementsOf(expected);
						})));
	}

