		SimpleDataset dataset = new SimpleDataset();
		dataset.setExplicitReadDataset(true);
		Graph graph = new Graph(Var.of("g"), new SingletonSet());
		TupleExpr wrapper = new ThirdPartyTupleExpr(graph);
		Join join = new Join(new SingletonSet(), wrapper);
		TupleExpr plan = new QueryRoot(join);
		assertThatCode(() -> optimize(plan, dataset, EmptyBindingSet.getInstance())).doesNotThrowAnyException();
		assertThat(join.getRightArg()).isSameAs(wrapper);
